-- V6：收敛「普通用户」角色菜单授权
-- Task 35 验收：普通用户（test/test1）不应看到用户管理菜单/操作。
-- RuoYi 默认 seed 将全量系统管理菜单授予 test1(1761300000000000003) 与 test2(1761300000000000004) 演示角色，
-- 此处移除其系统管理相关菜单授权（用户/角色/菜单/部门/岗位/字典/参数/公告/日志/客户端/文件/OSS 及全部操作点/按钮），
-- 仅保留演示需要的通用项与后续资产业务菜单（对应 component 由 D6/D7 前端任务补充菜单时单独授权）。
DELETE FROM sys_role_menu WHERE menu_id IN (
  -- 系统管理目录
  1761400000000000001,
  -- 用户管理 Ctrl + 操作点
  1761400000000000100, 1761400000000001001, 1761400000000001002, 1761400000000001003,
  1761400000000001004, 1761400000000001005, 1761400000000001006, 1761400000000001007,
  1761400000000000131,
  -- 角色管理 Ctrl + 操作点
  1761400000000000101, 1761400000000001008, 1761400000000001009, 1761400000000001010,
  1761400000000001011, 1761400000000001012, 1761400000000000130,
  -- 菜单管理 Ctrl + 操作点
  1761400000000000102, 1761400000000001013, 1761400000000001014, 1761400000000001015,
  1761400000000001016,
  -- 部门管理 Ctrl + 操作点
  1761400000000000103, 1761400000000001017, 1761400000000001018, 1761400000000001019,
  1761400000000001020,
  -- 岗位管理 Ctrl + 操作点
  1761400000000000104, 1761400000000001021, 1761400000000001022, 1761400000000001023,
  1761400000000001024, 1761400000000001025,
  -- 字典管理 Ctrl + 操作点
  1761400000000000105, 1761400000000001026, 1761400000000001027, 1761400000000001028,
  1761400000000001029, 1761400000000001030,
  -- 参数设置 Ctrl + 操作点
  1761400000000000106, 1761400000000001031, 1761400000000001032, 1761400000000001033,
  1761400000000001034, 1761400000000001035,
  -- 通知公告 Ctrl + 操作点
  1761400000000000107, 1761400000000001036, 1761400000000001037, 1761400000000001038,
  1761400000000001039,
  -- 日志管理目录 + 操作/登录日志 + 操作点
  1761400000000000108, 1761400000000000500, 1761400000000001040, 1761400000000001041,
  1761400000000001042, 1761400000000000501, 1761400000000001043, 1761400000000001044,
  1761400000000001045, 1761400000000001050,
  -- 客户端管理 + 文件管理/文件配置 + 操作点
  1761400000000000123, 1761400000000000118, 1761400000000000133,
  1761400000000001600, 1761400000000001601, 1761400000000001602, 1761400000000001603,
  1761400000000001620, 1761400000000001621, 1761400000000001622, 1761400000000001623,
  -- 代码生成目录
  1761400000000000003,
  -- 演示菜单（测试菜单及子项）离散残留
  1761400000000000005
) AND role_id IN (1761300000000000003, 1761300000000000004);